@extends('layouts.app') @section('title','السلة') @section('content')<section class="mx-auto max-w-5xl px-4 py-12"><h1 class="text-3xl font-black">سلة المشتريات</h1>@if(!$cart)<p class="mt-6 rounded-xl bg-white p-8">السلة فارغة. <a class="underline" href="{{route('menu.index')}}">تصفح القائمة</a></p>@else<div class="mt-6 space-y-3">@foreach($cart as $key=>$item)<div class="flex flex-wrap items-center justify-between gap-4 rounded-xl bg-white p-4"><div><b>{{$item['name']}}</b><p class="text-sm text-stone-500">{{$item['price']}} للقطعة</p></div><form method="POST" action="{{route('cart.update',$key)}}" class="flex gap-2">@csrf @method('PATCH')<input class="w-20 rounded-lg border-stone-300" type="number" min="1" max="20" name="quantity" value="{{$item['quantity']}}"><button class="rounded-lg border px-3">تحديث</button></form><b>{{number_format($item['price']*$item['quantity'],2)}}</b><form method="POST" action="{{route('cart.destroy',$key)}}">@csrf @method('DELETE')<button class="text-red-700">حذف</button></form></div>@endforeach</div><div class="mt-6 flex flex-wrap items-center justify-between gap-4 rounded-xl bg-coffee-dark p-5 text-white"><b>الإجمالي: {{number_format(collect($cart)->sum(fn($i)=>$i['price']*$i['quantity']),2)}}</b><a class="rounded-lg bg-coffee-cream px-5 py-3 font-bold text-coffee-dark" href="{{route('checkout.show')}}">إتمام الطلب</a><form method="POST" action="{{route('cart.clear')}}">@csrf @method('DELETE')<button>إفراغ السلة</button></form></div>@endif</section>@endsection